def get_value(self, series, key):
    s = getattr(series, "_values", series)
    if isinstance(s, (ExtensionArray, Index)) and is_scalar(key):
        try:
            iloc = self.get_loc(key)

            # Return directly if the index doesn't need materialization
            return s[iloc]
        except KeyError:
            if len(self) > 0 and (self.holds_integer() or self.is_boolean()):
                raise
            elif is_integer(key):
                return s[key]

    # Avoid materializing the object if possible
    if isinstance(s, ExtensionArray) and not is_integer(key):
        # If `key` is not an integer and `s` is an ExtensionArray,
        # provide a safe lookup operation
        if hasattr(s, '_get_value'):
            return s._get_value(key)  # Use a custom method if available.

    s = com.values_from_object(series)
    k = com.values_from_object(key)

    k = self._convert_scalar_indexer(k, kind="getitem")
    try:
        return self._engine.get_value(s, k, tz=getattr(series.dtype, "tz", None))
    except KeyError as e1:
        if len(self) > 0 and (self.holds_integer() or self.is_boolean()):
            raise

        try:
            return libindex.get_value_at(s, key)
        except IndexError:
            raise
        except TypeError:
            if is_iterator(key):
                raise InvalidIndexError(key)
            else:
                raise e1
        except Exception:
            raise e1
    except TypeError:
        if is_scalar(key):
            raise IndexError(key)
        raise InvalidIndexError(key)
